import base64,io,zipfile,json,sys,time
from pathlib import Path
if __name__=="__main__":
    workspace=Path("/kaggle/working/acceleration-code");workspace.mkdir(exist_ok=False)
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(''))) as z:z.extractall(workspace)
    sys.path[:0]=[str(workspace/"src"),str(workspace)]
    from profile_acceleration_gpu import run
    roots=sorted({p.parent for p in Path("/kaggle/input").rglob("2018") if p.is_dir()}|{p.parent for p in Path("/kaggle/input").rglob("2020") if p.is_dir()})
    scope=json.loads((workspace/"scope.json").read_text())
    result=run(workspace/"metadata",scope,roots,"/kaggle/working/profile-results",max_seconds=420,steps=8)
    print(json.dumps(result))
